test-and-set.pseudocode:
def test_and_set(mem, addr):  # 하드웨어가 원자적으로 수행
    old = mem[addr]
    mem[addr] = 1
    return old

def acquire(mem, lock):
    while test_and_set(mem, lock) == 1:
        pass  # 이미 잠겨 있으면 스핀

def release(mem, lock):
    mem[lock] = 0  # 해제: 다음 TAS가 0을 받음

text-tokenization.pseudocode:
def bpe_train(words, num_merges):
    # words: {문자 튜플: 빈도}, 예: {('l','o','w'): 5}
    vocab, merges = dict(words), []
    for _ in range(num_merges):
        pairs = {}
        for w, f in vocab.items():  # 인접 기호 쌍 빈도
            for a, b in zip(w, w[1:]):
                pairs[(a, b)] = pairs.get((a, b), 0) + f
        if not pairs:
            break
        best = max(pairs, key=pairs.get)  # 최빈 쌍 병합
        merges.append(best)
        new_vocab = {}
        for w, f in vocab.items():
            out, i = [], 0
            while i < len(w):
                if w[i:i + 2] == best:  # 쌍이면 하나로 합침
                    out.append(w[i] + w[i + 1])
                    i += 2
                else:
                    out.append(w[i])
                    i += 1
            new_vocab[tuple(out)] = f
        vocab = new_vocab
    return merges  # 병합 규칙 순서 = 서브워드 어휘
